    {"es": "El vino de la casa se sirve por copa o por botella.", "en": "The house wine is available by the glass or by the bottle.", "eu": "Etxeko ardoa kopaka ala botilaka eskuragarri dago.", "ipa": "ðə haʊs waɪn ɪz əˈveɪləbl baɪ ðə ɡlɑːs ɔː baɪ ðə ˈbɒtl", "categoria": "Bar"},
    {"es": "Última ronda, por favor; cerramos la barra en diez minutos.", "en": "Last orders, please; we close the bar in ten minutes.", "eu": "Azken txanda, mesedez; barra hamar minututan ixten dugu.", "ipa": "lɑːst ˈɔːdəz pliːz wiː kləʊz ðə bɑːr ɪn ten ˈmɪnɪts", "categoria": "Bar"},
    {"es": "¿Le sirvo los refrescos ahora o esperamos a que llegue todo el grupo?", "en": "Shall I bring the soft drinks now, or wait for the whole party?", "eu": "Freskagarriak orain ekarriko ditut, ala talde osoa iritsi arte itxarongo dut?", "ipa": "ʃæl aɪ brɪŋ ðə sɒft drɪŋks naʊ ɔː weɪt fə ðə həʊl ˈpɑːti", "categoria": "Bar"},
    {"es": "Este vino espumoso se sirve bien frío a unos seis grados.", "en": "This sparkling wine is best served well chilled at about six degrees.", "eu": "Ardo apardun hau oso hotz zerbitzatzen da, sei gradu inguruan.", "ipa": "ðɪs ˈspɑːklɪŋ waɪn ɪz best sɜːvd wel tʃɪld ət əˈbaʊt sɪks dɪˈɡriːz", "categoria": "Bar"},
    {"es": "La cafetera de filtro tarda un momento; ¿le sirvo un cortado mientras?", "en": "The filter coffee takes a moment; may I get you an espresso while you wait?", "eu": "Iragazkiko kafeak une bat behar du; bitartean ebaki bat jarriko dizut?", "ipa": "ðə ˈfɪltə ˈkɒfi teɪks ə ˈməʊmənt meɪ aɪ ɡet juː ən eˈspresəʊ waɪl juː weɪt", "categoria": "Bar"},
    {"es": "¿Me permite empujar la barra? Está un poco resbaladiza con el rocío.", "en": "May I wipe down the bar? It's a little slippery from the condensation.", "eu": "Barra garbitu dezaket? Nolabait labaina dago kondentsazioagatik.", "ipa": "meɪ aɪ waɪp daʊn ðə bɑːr ɪts ə ˈlɪtl ˈslɪpəri frəm ðə ˌkɒndenˈseɪʃən", "categoria": "Bar"},
    {"es": "Tenemos una promoción dos por uno en cervezas hasta las ocho.", "en": "We run a two-for-one offer on beers until eight.", "eu": "Bi baten truke promozioa dugu garagardoetan zortzietara arte.", "ipa": "wiː rʌn ə tuː fə wʌn ˈɒfər ɒn bɪəz ənˈtɪl eɪt", "categoria": "Bar"},
    {"es": "La sangría se prepara al momento con fruta fresca de temporada.", "en": "The sangria is prepared to order with fresh seasonal fruit.", "eu": "Sangria sasoiko fruta freskoarekin berehala prestatzen da.", "ipa": "ðə sæŋˈɡriːə ɪz prɪˈpeəd tʊ ˈɔːdə wɪð freʃ ˈsiːzənl fruːt", "categoria": "Bar"},
    {"es": "¿Le abro una cuenta de bar para que cargue las consumiciones a la habitación?", "en": "Would you like me to open a bar tab charged to your room?", "eu": "Barrako kontu bat irekiko dizut kontsumizioak gelara kargatzeko?", "ipa": "wʊd juː laɪk miː tʊ ˈəʊpən ə bɑː tæb tʃɑːdʒd tə jɔː ruːm", "categoria": "Bar"},
    {"es": "Este cóctel sin alcohol es la opción fresca de verano más popular.", "en": "This zero-proof cocktail is our most popular summer cooler.", "eu": "Alkoholik gabeko koktel hau gure udako freskagarri ezagunena da.", "ipa": "ðɪs ˈzɪərəʊ pruːf ˈkɒkteɪl ɪz ˈaʊə məʊst ˈpɒpjʊlə ˈsʌmə ˈkuːlə", "categoria": "Bar"},
    {"es": "Las copas de vino se sirven a una medida estándar de ciento cincuenta mililitros.", "en": "Wine is poured by the glass to a standard one-fifty-millilitre measure.", "eu": "Ardoa kopaka ehun eta berrogeita hamar mililitroko neurri estandarrean zerbitzatzen da.", "ipa": "waɪn ɪz pɔːd baɪ ðə ɡlɑːs tʊ ə ˈstændəd wʌn ˈfɪfti ˈmɪlɪliːtə ˈmeʒə", "categoria": "Bar"},
    {"es": "¿Tiene el carné encima? Necesito verificar la edad para el alcohol.", "en": "May I see some ID to confirm you're of legal drinking age?", "eu": "Adina egiaztatzeko dokumenturen bat erakutsi beharko zenidake.", "ipa": "meɪ aɪ siː sʌm ˌaɪ ˈdiː tə kənˈfɜːm jɔːr əv ˈliːɡl ˈdrɪŋkɪŋ eɪdʒ", "categoria": "Bar"},

    # ─────────────────────────────────────────────────────────────────────
    # COCINA (22)
    # ─────────────────────────────────────────────────────────────────────
    {"es": "La mise en place debe estar lista antes del inicio del servicio.", "en": "The mise en place must be ready before service starts.", "eu": "Mise en place zerbitzua hasi aurretik prest egon behar da.", "ipa": "ðə ˌmiːz ɒn ˈplɑːs mʌst biː ˈredi bɪˈfɔː ˈsɜːvɪs stɑːts", "categoria": "Cocina"},
    {"es": "Sellamos la carne a fuego fuerte para que conserve los jugos.", "en": "We sear the meat on high heat to lock in the juices.", "eu": "Haragia su bizi gainean zigilatzen dugu zukuak gordetzeko.", "ipa": "wiː sɪə ðə miːt ɒn haɪ hiːt tə lɒk ɪn ðə ˈdʒuːsɪz", "categoria": "Cocina"},
    {"es": "El caldo base se reduce a fuego lento durante varias horas.", "en": "The stock is simmered over a low flame for several hours.", "eu": "Salda su motelean ordu batzuetan zehar murrizten da.", "ipa": "ðə stɒk ɪz ˈsɪməd ˈəʊvər ə ləʊ fleɪm fə ˈsevrəl ˈaʊəz", "categoria": "Cocina"},
    {"es": "Pásame la espátula y sube la plancha a temperatura media.", "en": "Hand me the spatula and turn the griddle up to medium.", "eu": "Espatula pasa iezadazu eta plancha igo tenperatura ertainera.", "ipa": "hænd miː ðə ˈspætʃʊlə ænd tɜːn ðə ˈɡrɪdl ʌp tə ˈmiːdiəm", "categoria": "Cocina"},
    {"es": "El pescado se cocina al vapor para que quede jugoso y no se reseque.", "en": "The fish is steamed so it stays moist and never dries out.", "eu": "Arraina lurrunetan prestatzen da mamitsua mantendu eta lehor ez dadin.", "ipa": "ðə fɪʃ ɪz stiːmd səʊ ɪt steɪz mɔɪst ænd ˈnevə draɪz aʊt", "categoria": "Cocina"},
    {"es": "Batimos la nata hasta montarla y la guardamos en cámara fría.", "en": "We whip the cream to stiff peaks and store it in the cold room.", "eu": "Esne-gaina harrotu arte astintzen dugu eta hotz-ganberan gordetzen dugu.", "ipa": "wiː wɪp ðə kriːm tə stɪf piːks ænd stɔːr ɪt ɪn ðə kəʊld ruːm", "categoria": "Cocina"},
    {"es": "Marca la comanda con la hora y el número de mesa antes de colgarla.", "en": "Tag the ticket with the time and table number before you hang it.", "eu": "Eskaera-orria ordu eta mahai-zenbakiarekin markatu zintzilikatu aurretik.", "ipa": "tæɡ ðə ˈtɪkɪt wɪð ðə taɪm ænd ˈteɪbl ˈnʌmbə bɪˈfɔː juː hæŋ ɪt", "categoria": "Cocina"},
    {"es": "La salsa se espesa con un roux de mantequilla y harina.", "en": "The sauce is thickened with a roux of butter and flour.", "eu": "Saltsa gurin eta irinezko roux batekin loditzen da.", "ipa": "ðə sɔːs ɪz ˈθɪkənd wɪð ə ruː əv ˈbʌtər ænd ˈflaʊə", "categoria": "Cocina"},
    {"es": "Ponemos las verduras a escaldar y después las refrescamos en agua helada.", "en": "We blanch the vegetables and then refresh them in ice water.", "eu": "Barazkiak galdarraztatu eta gero izotz-uretan freskatzen ditugu.", "ipa": "wiː blɑːntʃ ðə ˈvedʒtəblz ænd ðen rɪˈfreʃ ðem ɪn aɪs ˈwɔːtə", "categoria": "Cocina"},
    {"es": "El horno de convección reparte el calor de manera uniforme.", "en": "The convection oven distributes the heat evenly.", "eu": "Konbekzio-labeak beroa modu uniformean banatzen du.", "ipa": "ðə kənˈvekʃən ˈʌvn dɪˈstrɪbjuːts ðə hiːt ˈiːvnli", "categoria": "Cocina"},
    {"es": "Escurre la pasta y amorosamente incorpora la salsa sin sobrecocerla.", "en": "Drain the pasta and toss it gently in the sauce without overcooking it.", "eu": "Pasta iragazi eta saltsan samur nahastu, gehiegi egosi gabe.", "ipa": "dreɪn ðə ˈpæstə ænd tɒs ɪt ˈdʒentli ɪn ðə sɔːs wɪˈðaʊt ˌəʊvəˈkʊkɪŋ ɪt", "categoria": "Cocina"},
    {"es": "La tabla de cortar se desinfecta entre el pollo crudo y las verduras.", "en": "The chopping board is sanitised between raw chicken and vegetables.", "eu": "Ebakitzeko taula oilasko gordina eta barazkien artean desinfektatzen da.", "ipa": "ðə ˈtʃɒpɪŋ bɔːd ɪz ˈsænɪtaɪzd bɪˈtwiːn rɔː ˈtʃɪkɪn ænd ˈvedʒtəblz", "categoria": "Cocina"},
    {"es": "Reposamos la masa tapada para que leve y doble su volumen.", "en": "We proof the dough covered so it rises and doubles in size.", "eu": "Orea estalita bere horretan utzi dugu harrotu eta bikoiztu dadin.", "ipa": "wiː pruːf ðə dəʊ ˈkʌvəd səʊ ɪt ˈraɪzɪz ænd ˈdʌblz ɪn saɪz", "categoria": "Cocina"},
    {"es": "El cuchillo de chef se afila cada mañana antes del servicio.", "en": "The chef's knife is sharpened every morning before service.", "eu": "Sukaldari-labana goizero zorrozten da zerbitzua hasi aurretik.", "ipa": "ðə ʃefs naɪf ɪz ˈʃɑːpənd ˈevri ˈmɔːnɪŋ bɪˈfɔː ˈsɜːvɪs", "categoria": "Cocina"},
    {"es": "Montamos el plato con la guarnición en su sitio y un toque de salsa reducida.", "en": "We plate the dish with the garnish in place and a touch of reduced sauce.", "eu": "Platera lagungarria bere lekuan eta saltsa murriztuaren ukitu batekin muntatzen dugu.", "ipa": "wiː pleɪt ðə dɪʃ wɪð ðə ˈɡɑːnɪʃ ɪn pleɪs ænd ə tʌtʃ əv rɪˈdjuːst sɔːs", "categoria": "Cocina"},
    {"es": "El aceite de la freidora se filtra a diario para mantenerlo limpio.", "en": "The fryer oil is filtered daily to keep it clean.", "eu": "Frijigailuaren olioa egunero iragazten da garbi mantentzeko.", "ipa": "ðə ˈfraɪər ɔɪl ɪz ˈfɪltəd ˈdeɪli tə kiːp ɪt kliːn", "categoria": "Cocina"},
    {"es": "Pochamos la cebolla a fuego suave hasta que quede translúcida.", "en": "We sweat the onion over a gentle heat until translucent.", "eu": "Tipula su motelean erregosten dugu zeharrargi geratu arte.", "ipa": "wiː swet ðiː ˈʌnjən ˈəʊvər ə ˈdʒentl hiːt ənˈtɪl trænzˈluːsnt", "categoria": "Cocina"},
    {"es": "Emplata de inmediato, que la sala está esperando la mesa ocho.", "en": "Plate at once — the front of house is waiting on table eight.", "eu": "Berehala muntatu, aretoa zortzigarren mahaiaren zain baitago.", "ipa": "pleɪt ət wʌns ðə frʌnt əv haʊs ɪz ˈweɪtɪŋ ɒn ˈteɪbl eɪt", "categoria": "Cocina"},
    {"es": "La temperatura del core del asado debe alcanzar los setenta grados.", "en": "The core temperature of the roast must reach seventy degrees.", "eu": "Errekiaren barruko tenperaturak hirurogeita hamar gradura iritsi behar du.", "ipa": "ðə kɔː ˈtemprətʃər əv ðə rəʊst mʌst riːtʃ ˈsevnti dɪˈɡriːz", "categoria": "Cocina"},
    {"es": "El pan de masa madre se fermenta en frío durante toda la noche.", "en": "The sourdough bread is cold-fermented overnight.", "eu": "Ogi-legamia duen ogia gau osoan hotzean hartzitzen da.", "ipa": "ðə ˈsaʊədəʊ bred ɪz kəʊld fəˈmentɪd ˌəʊvəˈnaɪt", "categoria": "Cocina"},
    {"es": "Etiquetamos cada contenedor con la fecha de elaboración y de caducidad.", "en": "We label every container with the prep and use-by dates.", "eu": "Ontzi bakoitza egite-data eta iraungitze-datarekin etiketatzen dugu.", "ipa": "wiː ˈleɪbl ˈevri kənˈteɪnə wɪð ðə prep ænd juːz baɪ deɪts", "categoria": "Cocina"},
    {"es": "Sala un plato y comunica que ya está listo para recoger.", "en": "Fire the dish and let the pass know it's ready for pickup.", "eu": "Platera atera eta komandakoari jaso dezakeela jakinarazi.", "ipa": "ˈfaɪə ðə dɪʃ ænd let ðə pɑːs nəʊ ɪts ˈredi fə ˈpɪkʌp", "categoria": "Cocina"},

    # ─────────────────────────────────────────────────────────────────────
    # LIMPIEZA / PISOS (22)
    # ─────────────────────────────────────────────────────────────────────
    {"es": "La habitación está ocupada; no limpie hasta que el huésped haya salido.", "en": "The room is occupied; do not clean until the guest has left.", "eu": "Gela okupatuta dago; ez garbitu bezeroa atera arte.", "ipa": "ðə ruːm ɪz ˈɒkjʊpaɪd duː nɒt kliːn ənˈtɪl ðə ɡest hæz left", "categoria": "Limpieza"},
    {"es": "Cambio la ropa de cama cada tres días o cuando se solicite.", "en": "Bed linen is changed every three days or on request.", "eu": "Oheko arropa hiru egunetik behin ala eskatzean aldatzen dut.", "ipa": "bed ˈlɪnɪn ɪz tʃeɪndʒd ˈevri θriː deɪz ɔːr ɒn rɪˈkwest", "categoria": "Limpieza"},
    {"es": "Reponemos las amenidades del baño: champú, gel y pastilla de jabón.", "en": "We restock the bathroom amenities: shampoo, shower gel, and soap.", "eu": "Bainugelako osagarriak berritzen ditugu: xanpua, gel-a eta xaboia.", "ipa": "wiː riːˈstɒk ðə ˈbɑːθruːm əˈmiːnətiz ʃæmˈpuː ˈʃaʊə dʒel ænd səʊp", "categoria": "Limpieza"},
    {"es": "Pase la aspiradora por la moqueta y después friegue el suelo de baldosa.", "en": "Vacuum the carpet, then mop the tiled floor.", "eu": "Alfonbra xurgagailua pasa eta gero baldosazko zorua garbitu.", "ipa": "ˈvækjuːm ðə ˈkɑːpɪt ðen mɒp ðə taɪld flɔː", "categoria": "Limpieza"},
    {"es": "El carrito de limpieza se aparca contra la pared para no obstruir el pasillo.", "en": "Park the housekeeping trolley against the wall so it doesn't block the corridor.", "eu": "Garbiketa-orga paretaren kontra aparkatu korridorea ez oztopatzeko.", "ipa": "pɑːk ðə ˈhaʊskiːpɪŋ ˈtrɒli əˈɡenst ðə wɔːl səʊ ɪt ˈdʌznt blɒk ðə ˈkɒrɪdɔː", "categoria": "Limpieza"},
    {"es": "Desinfectamos los interruptores y los pomos de las puertas a diario.", "en": "We disinfect the light switches and door handles daily.", "eu": "Argi-etengailuak eta ate-heldulekuak egunero desinfektatzen ditugu.", "ipa": "wiː ˌdɪsɪnˈfekt ðə laɪt ˈswɪtʃɪz ænd dɔː ˈhændlz ˈdeɪli", "categoria": "Limpieza"},
    {"es": "¿Desea que le haga la habitación ahora o más tarde?", "en": "Would you like your room made up now or later?", "eu": "Gela orain ala geroago zuzendu nahi duzu?", "ipa": "wʊd juː laɪk jɔː ruːm meɪd ʌp naʊ ɔː ˈleɪtə", "categoria": "Limpieza"},
    {"es": "El minibar se revisa y se repone durante la limpieza de la tarde.", "en": "The minibar is checked and restocked during the afternoon cleaning.", "eu": "Minibarra arratsaldeko garbiketan berrikusten da.", "ipa": "ðə ˈmɪnibɑːr ɪz tʃekt ænd riːˈstɒkt ˈdjʊərɪŋ ðiː ˌɑːftəˈnuːn ˈkliːnɪŋ", "categoria": "Limpieza"},
    {"es": "Guardo los objetos de valor del huésped donde indique, sin moverlos sin permiso.", "en": "I leave guests' valuables exactly where they are, never moved without consent.", "eu": "Bezeroen gauza baliotsuak dauden lekuan uzten ditut, baimenik gabe inoiz ez mugitu.", "ipa": "aɪ liːv ɡests ˈvæljʊəblz ɪɡˈzæktli weə ðeɪ ɑː ˈnevə muːvd wɪˈðaʊt kənˈsent", "categoria": "Limpieza"},
    {"es": "El letrero de «no molestar» debe respetarse en todo momento.", "en": "A 'do not disturb' sign must be respected at all times.", "eu": "«Ez molestatu» kartela beti errespetatu behar da.", "ipa": "ə duː nɒt dɪˈstɜːb saɪn mʌst biː rɪˈspektɪd ət ɔːl taɪmz", "categoria": "Limpieza"},
    {"es": "La toalla del suelo se cambia sola si se deja en la bañera.", "en": "The floor towel is replaced only when left in the tub.", "eu": "Lurreko toalla bainuontzian uzten denean bakarrik aldatzen da.", "ipa": "ðə flɔː ˈtaʊəl ɪz rɪˈpleɪst ˈəʊnli wen left ɪn ðə tʌb", "categoria": "Limpieza"},
    {"es": "Limpiamos los cristales con un paño de microfibra para evitar marcas.", "en": "We clean the glass with a microfibre cloth to avoid streaks.", "eu": "Kristalak mikrozuntzezko trapuz garbitzen ditugu orbainik ez uzteko.", "ipa": "wiː kliːn ðə ɡlɑːs wɪð ə ˈmaɪkrəʊfaɪbə klɒθ tʊ əˈvɔɪd striːks", "categoria": "Limpieza"},
    {"es": "La colada se plancha y se dobla en la lencería antes de subirla a los pisos.", "en": "The laundry is ironed and folded in the linen room before going up to the floors.", "eu": "Arropa lisatu eta tolesten da dentzategian, pisuetara igo aurretik.", "ipa": "ðə ˈlɔːndri ɪz ˈaɪənd ænd ˈfəʊldɪd ɪn ðə ˈlɪnɪn ruːm bɪˈfɔː ˈɡəʊɪŋ ʌp tə ðə flɔːz", "categoria": "Limpieza"},
    {"es": "Rellene la ficha de incidencias si falta alguna bombilla o mando.", "en": "Fill in the room report if any bulb or remote is missing.", "eu": "Inzidentzia-orria bete bonbilla edo aginteren bat falta bada.", "ipa": "fɪl ɪn ðə ruːm rɪˈpɔːt ɪf ˈeni bʌlb ɔː rɪˈməʊt ɪz ˈmɪsɪŋ", "categoria": "Limpieza"},
    {"es": "Se cambia el edredón al final de cada estancia larga o cuando esté manchado.", "en": "The duvet is changed at the end of each long stay or when soiled.", "eu": "Edredoia egonaldi luze bakoitzaren amaieran ala zikinduta dagoenean aldatzen da.", "ipa": "ðə ˈduːveɪ ɪz tʃeɪndʒd ət ðiː end əv iːtʃ lɒŋ steɪ ɔː wen sɔɪld", "categoria": "Limpieza"},
    {"es": "La habitación de salida se revisa en busca de objetos olvidados.", "en": "The departure room is checked for lost property.", "eu": "Irteerako gela galdutako objektuen bila berrikusten da.", "ipa": "ðə dɪˈpɑːtʃə ruːm ɪz tʃekt fə lɒst ˈprɒpəti", "categoria": "Limpieza"},
    {"es": "Usamos guantes y mascarilla al manipular los productos de limpieza.", "en": "We wear gloves and a mask when handling cleaning products.", "eu": "Eskularruak eta maskara erabiltzen ditugu garbiketa-produktuak erabiltzean.", "ipa": "wiː weə ɡlʌvz ænd ə mɑːsk wen ˈhændlɪŋ ˈkliːnɪŋ ˈprɒdʌkts", "categoria": "Limpieza"},
    {"es": "El espejo del baño se limpia en último lugar para que quede impecable.", "en": "The bathroom mirror is polished last so it's left spotless.", "eu": "Bainugelako ispilua azkenean garbitzen da orbangabe gera dadin.", "ipa": "ðə ˈbɑːθruːm ˈmɪrər ɪz ˈpɒlɪʃt lɑːst səʊ ɪts left ˈspɒtləs", "categoria": "Limpieza"},
